def large_rects(g, min_area=20):
 h,w=len(g),len(g[0]); R=[]
 for top in range(h):
  for v in set(g[top]):
   cols=[True]*w
   for bot in range(top,h):
    cols=[cols[c] and g[bot][c]==v for c in range(w)]
    c=0
    while c<w:
     if not cols[c]: c+=1; continue
     s=c
     while c<w and cols[c]: c+=1
     e=c-1; area=(bot-top+1)*(e-s+1)
     if area>=min_area:
      # maximal if can't expand vertically fully over width, or horizontally (run maximal for band)
      up=top>0 and all(g[top-1][x]==v for x in range(s,e+1))
      down=bot<h-1 and all(g[bot+1][x]==v for x in range(s,e+1))
      left=s>0 and all(g[y][s-1]==v for y in range(top,bot+1))
      right=e<w-1 and all(g[y][e+1]==v for y in range(top,bot+1))
      if not (up or down or left or right):
       R.append((area,v,top,bot,s,e))
 return sorted(R,reverse=True)
